use vsa;

program CotChain implements ISolve {
    public function solve(mention: str): str {
        create frame: number;
        bind frame, H1_COUNTRY_OF_CITIZENSHIP, "iso 3166-1:ke";
        bind frame, H2_DIPLOMATIC_RELATION, "south-west nigeria";
        bind frame, H3_HEAD_OF_STATE, "Jonathan Goodluck";
        return recover(frame, H1_COUNTRY_OF_CITIZENSHIP);
    }

    public function hop_2(): str {
        create frame: number;
        bind frame, H1_COUNTRY_OF_CITIZENSHIP, "iso 3166-1:ke";
        bind frame, H2_DIPLOMATIC_RELATION, "south-west nigeria";
        bind frame, H3_HEAD_OF_STATE, "Jonathan Goodluck";
        return recover(frame, H2_DIPLOMATIC_RELATION);
    }

    public function hop_3(): str {
        create frame: number;
        bind frame, H1_COUNTRY_OF_CITIZENSHIP, "iso 3166-1:ke";
        bind frame, H2_DIPLOMATIC_RELATION, "south-west nigeria";
        bind frame, H3_HEAD_OF_STATE, "Jonathan Goodluck";
        return recover(frame, H3_HEAD_OF_STATE);
    }

    public function control(): str {
        create frame: number;
        bind frame, H1_COUNTRY_OF_CITIZENSHIP, "iso 3166-1:ke";
        bind frame, H2_DIPLOMATIC_RELATION, "south-west nigeria";
        bind frame, H3_HEAD_OF_STATE, "Jonathan Goodluck";
        return recover(frame, ABSENT_CTRL);
    }
}

