use vsa;

program CotChain implements ISolve {
    public function solve(mention: str): str {
        create frame: number;
        bind frame, H1_NATIVE_LANGUAGE, "french vocabulary";
        bind frame, H2_LINGUISTIC_TYPOLOGY, "Fusional";
        return recover(frame, H1_NATIVE_LANGUAGE);
    }

    public function hop_2(): str {
        create frame: number;
        bind frame, H1_NATIVE_LANGUAGE, "french vocabulary";
        bind frame, H2_LINGUISTIC_TYPOLOGY, "Fusional";
        return recover(frame, H2_LINGUISTIC_TYPOLOGY);
    }

    public function control(): str {
        create frame: number;
        bind frame, H1_NATIVE_LANGUAGE, "french vocabulary";
        bind frame, H2_LINGUISTIC_TYPOLOGY, "Fusional";
        return recover(frame, ABSENT_CTRL);
    }
}

